mapper.insert:
INSERT INTO scheduled_agent_task (
    name, prompt, schedule_type, schedule_expr,
    enabled, next_run_at
) VALUES (
    #{name}, #{prompt}, #{scheduleType}, #{scheduleExpr},
    #{enabled}, #{nextRunAt}
)

mapper.select:
SELECT * FROM scheduled_agent_task
WHERE id = #{id}
LIMIT 1

SELECT id FROM scheduled_agent_task
WHERE enabled = 1
  AND next_run_at <= #{now}
  AND (lock_until IS NULL OR lock_until < #{now})
ORDER BY next_run_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE scheduled_agent_task
SET lock_until = #{lockUntil},
    lock_owner = #{lockOwner},
    running = 1,
    update_time = #{now}
WHERE id = #{id}
  AND (lock_until IS NULL OR lock_until < #{now})
  AND enabled = 1
  AND next_run_at <= #{now}
